effect.shader:
#define iTime (0.0)
#define iResolution vec3(acScreenSize, 1.0)
#define iDate vec4(0.0, 0.0, 0.0, iTime)
#define iMouse vec4(acScreenSize * 0.5, 0.0, 0.0)
void gmGeneratedMainImage( out vec4 fragColor, in vec2 fragCoord )
{
vec2 p = fragCoord.xy / iResolution.x;
float prop = iResolution.x / iResolution.y;
vec2 m = vec2(lensCenterX, lensCenterY / prop);
vec2 d = p - m;
float r = sqrt(dot(d, d));
float power = ( 2.0 * 3.141592 / (2.0 * sqrt(dot(m, m))) ) *
lensStrength;
float bind;
if (power > 0.0) bind = sqrt(dot(m, m));
else {if (prop < 1.0) bind = m.x; else bind = m.y;} bind *= lensRadius;
vec2 uv;
if (power > 0.0)
uv = m + d / max(length(d), 0.00001) * tan(r * power) * bind / tan( bind * power);
else if (power < 0.0)
uv = m + d / max(length(d), 0.00001) * atan(r * -power * 10.0) * bind / atan(-power * bind * 10.0);
else uv = p;
vec3 col = texture2DCv(inputImg.texture, vec2(uv.x, uv.y * prop)).xyz;
fragColor = vec4(col, 1.0);
}
void main(){
vec4 gmGenerated=vec4(0.0);
gmGeneratedMainImage(gmGenerated,acScreenNorm*acScreenSize);
vec4 gmSource=texture2DCv(inputImg.texture,acScreenNorm);
float gmAlpha=gmClip?gmSource.a:gmGenerated.a;
vec4 gmResult=vec4(gmGenerated.rgb*gmAlpha,gmAlpha);
gl_FragColor=mix(gmSource,gmResult,gmMix);
}
